    onSuccess: (data) => {
      setUploadedUrl(data.url);
      setUploadedName(data.originalName);
      setError(null);
    },
    onError: (err) => {
      setError(err.message);
      setUploadedUrl(null);
      setUploadedName(null);
    },
  });

